-- WP-04: profile detail, professional verification, private object metadata,
-- consent and care access.
--
-- Design rules this migration follows, all inherited from the existing
-- foundation rather than invented here:
--   * every identifier is a PostgreSQL 18 `uuidv7()` uuid generated by the
--     application inside the same transaction as the aggregate write;
--   * optimistic concurrency uses an integer `version` column with a `>= 0`
--     check, so a stale writer is rejected instead of silently overwriting;
--   * any foreign key that could cross an organization boundary is COMPOSITE
--     and includes `organization_id`, following the
--     `membership_sites_membership_org_fk` / `membership_sites_site_org_fk`
--     precedent from migration 0008. A single-column reference would let a row
--     in organization A point at a resource in organization B, which no
--     application-level guard can retroactively repair;
--   * `verification_status` is REUSED, not redefined. The membership-level
--     column already exists on `organization_memberships`; the per-document
--     column added here is a narrower instance of the same vocabulary;
--   * permissions are seeded per action. No `*` action is introduced, because
--     `permissionMatches` treats `*` as matching every present and future
--     action, and migrations 0009/0010 deliberately removed the last wildcard.
--
-- Preflight: this migration creates nine tables, ten enum types and several
-- composite foreign keys whose target unique indexes must already exist. It
-- also seeds `role_permissions` rows whose `role_id` foreign key can only be
-- satisfied by the roles seeded in 0004. Rather than letting any of that abort
-- with an opaque server error, assert every precondition first and report the
-- specific missing object, following the precedent in migration 0008.
DO $$
DECLARE
  server_version integer;
  missing_roles text;
  existing_tables text;
BEGIN
  -- PostgreSQL 18 is required: every primary key in this migration is written
  -- by the built-in `uuidv7()`, which does not exist before 18. Failing here is
  -- far cheaper than discovering it on the first INSERT.
  SELECT current_setting('server_version_num')::integer INTO server_version;
  IF server_version < 180000 THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: PostgreSQL 18 or newer is required for built-in uuidv7(), found server_version_num=%.',
      server_version;
  END IF;

  -- The composite membership foreign keys below reference
  -- (membership_id, organization_id). PostgreSQL requires a unique index on
  -- exactly those columns; migration 0008 created it. If a hand-edited database
  -- lost it, ADD CONSTRAINT would fail with a generic "no unique constraint
  -- matching given keys" message that hides which index is missing.
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public'
      AND indexname = 'organization_memberships_id_org_uq'
  ) THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: unique index organization_memberships_id_org_uq is missing. Migration 0008 must be applied before this migration.';
  END IF;

  -- The role_permissions seed at the end of this migration has a foreign key to
  -- roles. A partially seeded roles table would abort the migration after the
  -- DDL has already run, so check the full system role set up front.
  SELECT COALESCE(string_agg(expected.role_id, ', ' ORDER BY expected.role_id), '')
  INTO missing_roles
  FROM (VALUES
    ('patient'), ('doctor'), ('driver'), ('pharmacy'),
    ('emergency'), ('admin'), ('super_admin')
  ) AS expected(role_id)
  WHERE NOT EXISTS (
    SELECT 1 FROM roles WHERE roles.role_id = expected.role_id
  );

  IF missing_roles <> '' THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: required system role(s) missing from roles: %. Migration 0004 must be applied before this migration.',
      missing_roles;
  END IF;

  -- Guard against a partially applied earlier attempt. CREATE TABLE without
  -- IF NOT EXISTS is intentional (silently skipping a table would leave the
  -- schema out of step with the drizzle snapshot), so report every conflicting
  -- relation at once instead of stopping at the first one.
  SELECT COALESCE(string_agg(candidate.table_name, ', ' ORDER BY candidate.table_name), '')
  INTO existing_tables
  FROM (VALUES
    ('profile_addresses'), ('profile_emergency_contacts'), ('profile_allergies'),
    ('profile_conditions'), ('doctor_details'), ('doctor_specialties'),
    ('doctor_languages'), ('stored_objects'), ('verification_documents'),
    ('consent_grants'), ('care_assignments')
  ) AS candidate(table_name)
  WHERE to_regclass('public.' || candidate.table_name) IS NOT NULL;

  IF existing_tables <> '' THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: table(s) already exist from a partially applied attempt: %. Drop them deliberately or repair the drizzle journal before retrying.',
      existing_tables;
  END IF;
END;
$$;--> statement-breakpoint
