-- Time-bounded clinician-to-patient care relationship. `policy-matrix.md` makes
-- an active assignment (not organization membership) the object-relationship
-- test for ordinary clinical access, so this table is authorization input and
-- must never be mutated in place to "fix" history: it is closed with
-- `ended_at` and a reason instead.
CREATE TABLE "care_assignments" (
	"assignment_id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"clinician_membership_id" uuid NOT NULL,
	"patient_profile_id" uuid NOT NULL,
	"status" "care_assignment_status" DEFAULT 'active' NOT NULL,
	"assigned_at" timestamp with time zone DEFAULT now() NOT NULL,
	"ended_at" timestamp with time zone,
	"ended_reason" varchar(64),
	"assigned_by_membership_id" uuid,
	"version" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "care_assignments_version_check" CHECK ("care_assignments"."version" >= 0),
	-- An assignment cannot end before it began; a clock skew or a bad manual
	-- correction would otherwise create a negative-duration care window that
	-- reads as "valid at time T" for arbitrary T.
	CONSTRAINT "care_assignments_ended_order_check" CHECK ("care_assignments"."ended_at" IS NULL OR "care_assignments"."ended_at" >= "care_assignments"."assigned_at"),
	-- `status = 'active'` and `ended_at IS NULL` are the same fact expressed two
	-- ways. Binding them with an equivalence removes the "revoked but still
	-- open" and "ended but still active" rows that would make an authorization
	-- query answer differently depending on which column it trusted.
	CONSTRAINT "care_assignments_lifecycle_check" CHECK (("care_assignments"."status" = 'active') = ("care_assignments"."ended_at" IS NULL)),
	CONSTRAINT "care_assignments_ended_reason_check" CHECK ("care_assignments"."ended_reason" IS NULL OR "care_assignments"."ended_at" IS NOT NULL)
);
