-- Explicit patient consent. The grantee is either another profile (a guardian
-- or dependant arrangement) or an organization membership (a clinician or staff
-- member). Expiry and revocation are separate facts: an expired grant lapsed on
-- its own, a revoked grant was withdrawn by someone and therefore carries a
-- reason code and participates in audit.
CREATE TABLE "consent_grants" (
	"consent_id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"grantor_profile_id" uuid NOT NULL,
	"grantee_profile_id" uuid,
	"grantee_membership_id" uuid,
	"scope" "consent_scope" NOT NULL,
	"purpose" varchar(160) NOT NULL,
	"granted_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	"revocation_reason" "consent_revocation_reason",
	"version" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "consent_grants_version_check" CHECK ("consent_grants"."version" >= 0),
	-- Exactly one grantee. Both columns set would make "who may act on this
	-- grant" ambiguous; neither set would create a grant that authorises nobody
	-- yet still appears in a consent list.
	CONSTRAINT "consent_grants_grantee_exclusive_check" CHECK (("consent_grants"."grantee_profile_id" IS NOT NULL) <> ("consent_grants"."grantee_membership_id" IS NOT NULL)),
	-- A profile cannot consent to itself. `own` access is a property of
	-- ownership, never of consent, and a self-grant would let a revocation of
	-- consent be misread as a removal of the owner's own access.
	CONSTRAINT "consent_grants_self_grant_check" CHECK ("consent_grants"."grantee_profile_id" IS NULL OR "consent_grants"."grantee_profile_id" <> "consent_grants"."grantor_profile_id"),
	CONSTRAINT "consent_grants_expiry_order_check" CHECK ("consent_grants"."expires_at" IS NULL OR "consent_grants"."expires_at" > "consent_grants"."granted_at"),
	CONSTRAINT "consent_grants_revocation_order_check" CHECK ("consent_grants"."revoked_at" IS NULL OR "consent_grants"."revoked_at" >= "consent_grants"."granted_at"),
	-- A revocation without a reason code cannot be reviewed, and a reason code
	-- without a revocation timestamp implies a revocation that never happened.
	CONSTRAINT "consent_grants_revocation_reason_check" CHECK (("consent_grants"."revoked_at" IS NULL) = ("consent_grants"."revocation_reason" IS NULL))
);
