-- Professional detail for a doctor MEMBERSHIP, not a profile. One profile may
-- hold several memberships (different organizations, or doctor plus patient),
-- and a fee, biography and registration number belong to the organization the
-- doctor practises in. Keying on `membership_id` makes that one-to-one by
-- construction instead of by application convention.
CREATE TABLE "doctor_details" (
	"membership_id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"biography" text,
	"registration_number" varchar(64),
	"years_of_experience" integer DEFAULT 0 NOT NULL,
	"consultation_fee_sen" integer DEFAULT 0 NOT NULL,
	"currency" varchar(3) DEFAULT 'MYR' NOT NULL,
	"accepting_new_patients" boolean DEFAULT true NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "doctor_details_version_check" CHECK ("doctor_details"."version" >= 0),
	CONSTRAINT "doctor_details_experience_check" CHECK ("doctor_details"."years_of_experience" >= 0 AND "doctor_details"."years_of_experience" <= 80),
	-- Money is integer MYR sen, never floating point ringgit. A negative
	-- consultation fee is not a discount, it is a payout, and the payment
	-- aggregate has no representation for that.
	CONSTRAINT "doctor_details_fee_check" CHECK ("doctor_details"."consultation_fee_sen" >= 0),
	-- Single-currency by decision, not by omission. Multi-currency pricing needs
	-- a reviewed FX and settlement design, so the constraint fails loudly rather
	-- than letting an unpriceable row through.
	CONSTRAINT "doctor_details_currency_check" CHECK ("doctor_details"."currency" = 'MYR')
);
