-- Authoritative metadata for every private file. The bytes live in object
-- storage; this row is the only thing the platform trusts about them.
--
-- CRITICAL INVARIANT: a file that is not finalized, or whose malware scan is
-- not clean, must never be downloadable. That is encoded structurally by the
-- `downloadable` flag plus `stored_objects_downloadable_check`: the flag may be
-- true only when the upload is finalized, the scan is clean and the verified
-- digest matches the digest the client declared. Every download path reads the
-- flag, so an in-progress, quarantined, infected, unscanned or tampered object
-- cannot be served even if application code forgets a predicate. The flag is a
-- plain column rather than a generated column so the check remains provably
-- immutable across PostgreSQL versions, and the constraint is one-directional
-- on purpose: the database refuses to CALL something downloadable, and never
-- promotes an object to downloadable on its own.
CREATE TABLE "stored_objects" (
	"object_id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"storage_provider" varchar(32) NOT NULL,
	"bucket" varchar(128) NOT NULL,
	"object_key" varchar(512) NOT NULL,
	"media_type" varchar(160) NOT NULL,
	"byte_size" bigint NOT NULL,
	"declared_sha256" varchar(64) NOT NULL,
	"verified_sha256" varchar(64),
	"upload_status" "stored_object_status" DEFAULT 'pending' NOT NULL,
	"scan_state" "malware_scan_state" DEFAULT 'not_scanned' NOT NULL,
	"downloadable" boolean DEFAULT false NOT NULL,
	"scanned_at" timestamp with time zone,
	"finalized_at" timestamp with time zone,
	"deleted_at" timestamp with time zone,
	"uploaded_by_profile_id" uuid NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "stored_objects_version_check" CHECK ("stored_objects"."version" >= 0),
	-- A zero-byte private file is always a failed or truncated upload. Rejecting
	-- it here keeps the "finalized" state honest.
	CONSTRAINT "stored_objects_byte_size_check" CHECK ("stored_objects"."byte_size" > 0),
	-- 64 lowercase hex characters. Mixed case would make two spellings of the
	-- same digest compare unequal, which silently breaks integrity comparison.
	CONSTRAINT "stored_objects_declared_sha256_check" CHECK ("stored_objects"."declared_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "stored_objects_verified_sha256_check" CHECK ("stored_objects"."verified_sha256" IS NULL OR "stored_objects"."verified_sha256" ~ '^[0-9a-f]{64}$'),
	-- The download invariant. A mismatch between declared and verified digest is
	-- deliberately storable (forensics need the evidence) but can never be
	-- downloadable.
	CONSTRAINT "stored_objects_downloadable_check" CHECK ("stored_objects"."downloadable" = false OR ("stored_objects"."upload_status" = 'finalized' AND "stored_objects"."scan_state" = 'clean' AND "stored_objects"."verified_sha256" IS NOT NULL AND "stored_objects"."verified_sha256" = "stored_objects"."declared_sha256")),
	-- Finalization means the server has seen the bytes and hashed them itself.
	-- Without a verified digest, "finalized" would only mean "the client said so".
	CONSTRAINT "stored_objects_finalized_checksum_check" CHECK ("stored_objects"."upload_status" <> 'finalized' OR ("stored_objects"."finalized_at" IS NOT NULL AND "stored_objects"."verified_sha256" IS NOT NULL)),
	CONSTRAINT "stored_objects_pending_finalized_at_check" CHECK ("stored_objects"."finalized_at" IS NULL OR "stored_objects"."upload_status" <> 'pending'),
	-- A terminal scan verdict must carry the time it was reached, and a
	-- not-yet-scanned object must not carry one. Otherwise scan freshness
	-- policies cannot distinguish "never scanned" from "scanned long ago".
	CONSTRAINT "stored_objects_scanned_at_check" CHECK (("stored_objects"."scan_state" IN ('not_scanned', 'scanning')) = ("stored_objects"."scanned_at" IS NULL)),
	CONSTRAINT "stored_objects_deleted_at_check" CHECK (("stored_objects"."upload_status" = 'deleted') = ("stored_objects"."deleted_at" IS NOT NULL))
);
