  ('consent.grant:revoke:own', 'Revoke a consent grant the authenticated profile granted'),
  ('consent.grant:read:assigned', 'Read consent grants covering an assigned patient'),
  ('consent.grant:read:organization', 'Read consent grant metadata recorded within the organization'),
