-- Post-seed least-privilege assertion. A wildcard action reaching any of the
-- WP-04 resources would re-open the hole that 0009/0010 closed, and a typo in a
-- role grant above would leave a role permanently short of authority. Both are
-- cheap to check here and expensive to discover in production.
DO $$
DECLARE
  wildcard_permissions text;
  clinical_admin_grants text;
BEGIN
  SELECT COALESCE(string_agg(candidate.permission_id, ', ' ORDER BY candidate.permission_id), '')
  INTO wildcard_permissions
  FROM (
    SELECT permission_id FROM permissions WHERE permission_id LIKE '%:*:%' OR permission_id LIKE '%:*'
  ) AS candidate
  WHERE candidate.permission_id LIKE 'verification.document:%'
     OR candidate.permission_id LIKE 'file.object:%'
     OR candidate.permission_id LIKE 'consent.grant:%'
     OR candidate.permission_id LIKE 'care.assignment:%'
     OR candidate.permission_id LIKE 'profile.clinical:%'
     OR candidate.permission_id LIKE 'profile.address:%'
     OR candidate.permission_id LIKE 'profile.emergency_contact:%'
     OR candidate.permission_id LIKE 'doctor.profile:%';

  IF wildcard_permissions <> '' THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: wildcard action permission(s) present for WP-04 resources: %. A `*` action matches every present and future action; seed explicit per-action permissions instead.',
      wildcard_permissions;
  END IF;

  -- Administrative rank must not confer clinical payload access. If a future
  -- edit grants a clinical permission to `admin` or `super_admin`, fail here
  -- rather than shipping it.
  SELECT COALESCE(string_agg(role_id || ' -> ' || permission_id, ', ' ORDER BY role_id, permission_id), '')
  INTO clinical_admin_grants
  FROM role_permissions
  WHERE role_id IN ('admin', 'super_admin')
    AND permission_id LIKE 'profile.clinical:%';

  IF clinical_admin_grants <> '' THEN
    RAISE EXCEPTION
      'Migration 0011 aborted: administrative role(s) were granted clinical permissions: %. policy-matrix.md denies clinical payload access to admin and super_admin.',
      clinical_admin_grants;
  END IF;
END;
$$;--> statement-breakpoint
-- New `profiles` compatibility component rather than a bump of `identity`.
--
-- `FoundationReadinessRepository` requires an EXACT version match for the
-- components it checks (`foundation` and `identity`), so bumping `identity`
-- without changing `IDENTITY_SCHEMA_VERSION` in the same deployment makes
-- readiness report 503. Nothing in the shipped identity code path changes here:
-- this migration only adds tables and additive permission rows. Registering the
-- WP-04 data model under its own component records the schema level without
-- coupling it to identity readiness, and leaves `IDENTITY_SCHEMA_VERSION`
-- untouched at 6.
INSERT INTO schema_compatibility (component, version)
VALUES ('profiles', 1)
ON CONFLICT (component) DO UPDATE
SET version = EXCLUDED.version, updated_at = now();
